#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005

int parent[MAXN];
int rank_sz[MAXN];

int find_set(int v) {
    if (v == parent[v])
        return v;
    return parent[v] = find_set(parent[v]);
}

int union_sets(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if (a != b) {
        if (rank_sz[a] < rank_sz[b]) {
            int tmp = a;
            a = b;
            b = tmp;
        }
        parent[b] = a;
        if (rank_sz[a] == rank_sz[b]) {
            rank_sz[a]++;
        }
        return 1;
    }
    return 0;
}

typedef struct {
    int u, v;
} Edge;

Edge rodovias[MAXN];

int main(void) {
    int n, m, k;
    if (scanf("%d %d %d", &n, &m, &k) != 3) {
        return 0;
    }

    for (int i = 1; i <= n; i++) {
        parent[i] = i;
        rank_sz[i] = 0;
    }

    int rodovias_count = 0;
    int hidrovia_has_cycle = 0;

    for (int i = 0; i < m; i++) {
        int u, v, t;
        scanf("%d %d %d", &u, &v, &t);
        if (t == 1) {
            if (!hidrovia_has_cycle) {
                if (!union_sets(u, v)) {
                    hidrovia_has_cycle = 1;
                }
            }
        } else {
            rodovias[rodovias_count].u = u;
            rodovias[rodovias_count].v = v;
            rodovias_count++;
        }
    }

    if (hidrovia_has_cycle) {
        printf("N\n");
        return 0;
    }

    int rodovias_removidas = 0;
    for (int i = 0; i < rodovias_count; i++) {
        if (!union_sets(rodovias[i].u, rodovias[i].v)) {
            rodovias_removidas++;
        }
    }

    if (rodovias_removidas <= k) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
